import { modelIdentifierSchema, reasoningEffortSchema, type DesktopModelPurpose } from "@linksense/shared";
import { z } from "zod";

import { sha256 } from "../../lib/crypto.js";
import { AppError } from "../../lib/errors.js";

export type ModelProxyEndpoint = "responses" | "chat/completions";

// Final user message generated by the bundled Codex 0.168.0 local compaction task.
const nativeCompactionPromptHash = "ab0c334d4faca17e3afbb9b16967c1b2fdcc7242a9a0880af57949fa236d6d07";
const identifier = z.string().min(1).max(256);
const imageData = z.string().regex(/^data:image\/(?:png|jpeg|webp|gif);base64,[A-Za-z0-9+/]+={0,2}$/u);
const detail = z.enum(["auto", "low", "high", "original"]).optional();
const functionFields = {
  name: identifier,
  description: z.string().optional(),
  strict: z.boolean().nullable().optional(),
  parameters: z.record(z.string(), z.unknown()).nullable().optional(),
};
const functionTool = z.strictObject({
  type: z.literal("function"), ...functionFields,
  defer_loading: z.boolean().optional(),
});
const customTool = z.strictObject({
  type: z.literal("custom"), name: identifier, description: z.string().optional(),
  format: z.union([
    z.strictObject({ type: z.literal("text") }),
    z.strictObject({ type: z.literal("grammar"), syntax: z.string(), definition: z.string() }),
  ]).optional(),
});
const responseTool = z.discriminatedUnion("type", [
  functionTool,
  customTool,
  z.strictObject({
    type: z.literal("namespace"), name: identifier, description: z.string().optional(),
    tools: z.array(z.union([functionTool, customTool])).max(256),
  }),
  z.strictObject({
    type: z.literal("tool_search"), execution: z.literal("client"),
    description: z.string().optional(), parameters: z.record(z.string(), z.unknown()).optional(),
  }),
  z.strictObject({ type: z.literal("web_search"), external_web_access: z.literal(false) }),
]);
const responseContent = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("input_text"), text: z.string() }),
  z.object({ type: z.literal("output_text"), text: z.string() }),
  z.strictObject({ type: z.literal("input_image"), image_url: imageData, detail }),
  z.strictObject({ type: z.literal("refusal"), refusal: z.string() }),
]);
const responseOutput = z.union([z.string(), z.array(responseContent).max(256)]);
const responseItem = z.discriminatedUnion("type", [
  z.strictObject({
    type: z.literal("message"), id: identifier.optional(),
    role: z.enum(["system", "developer", "user", "assistant"]),
    content: z.array(responseContent).max(256), phase: identifier.optional(), status: identifier.optional(),
  }),
  z.strictObject({
    type: z.literal("function_call"), id: identifier.optional(),
    call_id: identifier, name: identifier, namespace: identifier.optional(), arguments: z.string(),
    status: identifier.optional(),
  }),
  z.strictObject({
    type: z.literal("function_call_output"), id: identifier.optional(),
    call_id: identifier, output: responseOutput,
  }),
  z.strictObject({
    type: z.literal("custom_tool_call"), id: identifier.optional(),
    call_id: identifier, name: identifier, namespace: identifier.optional(),
    input: z.string(), status: identifier.optional(),
  }),
  z.strictObject({
    type: z.literal("custom_tool_call_output"), id: identifier.optional(),
    call_id: identifier, output: responseOutput,
  }),
  z.strictObject({
    type: z.literal("reasoning"), id: identifier.optional(),
    encrypted_content: z.string(),
    summary: z.array(z.strictObject({ type: z.literal("summary_text"), text: z.string() })).max(256),
    content: z.array(z.strictObject({ type: z.enum(["reasoning_text", "text"]), text: z.string() })).max(256).nullish(),
    context: z.string().optional(),
  }),
  z.strictObject({
    type: z.literal("compaction"), id: identifier.optional(), encrypted_content: z.string(),
  }),
  z.strictObject({
    type: z.literal("additional_tools"), id: identifier.optional(), role: z.literal("developer").optional(),
    tools: z.array(responseTool).max(256), content: z.array(responseContent).max(256).optional(),
  }),
  z.strictObject({
    type: z.literal("tool_search_call"), id: identifier.optional(),
    call_id: identifier.optional(), execution: z.literal("client").optional(),
    status: identifier.optional(), arguments: z.union([z.string(), z.record(z.string(), z.unknown())]),
  }),
  z.strictObject({
    type: z.literal("tool_search_output"), id: identifier.optional(),
    call_id: identifier.optional(), execution: z.literal("client").optional(),
    status: identifier.optional(), tools: z.array(responseTool).max(256),
  }),
]);
const outputLimit = z.number().int().positive().max(128_000).optional();
const responseRequest = z.strictObject({
  model: modelIdentifierSchema,
  input: z.union([z.string(), z.array(responseItem).max(4096)]),
  instructions: z.string().optional(),
  tools: z.array(responseTool).max(256).optional(),
  tool_choice: z.union([
    z.enum(["auto", "none", "required"]),
    z.strictObject({ type: z.literal("function"), name: identifier, namespace: identifier.optional() }),
  ]).optional(),
  parallel_tool_calls: z.boolean().optional(),
  reasoning: z.strictObject({
    effort: reasoningEffortSchema.nullable().optional(),
    summary: z.enum(["auto", "concise", "detailed", "none"]).nullable().optional(),
    context: z.enum(["auto", "current_turn", "all_turns"]).optional(),
  }).nullable().optional(),
  include: z.array(z.literal("reasoning.encrypted_content")).max(1).optional(),
  text: z.strictObject({ format: z.record(z.string(), z.unknown()).optional(), verbosity: z.enum(["low", "medium", "high"]).optional() }).nullable().optional(),
  store: z.literal(false).optional(),
  stream: z.boolean().optional(),
  max_output_tokens: outputLimit,
  // Native bookkeeping is local to Codex; never forward the client-supplied account or cache identity.
  client_metadata: z.record(z.string(), z.string()).optional(),
  prompt_cache_key: z.string().optional(),
  prompt_cache_options: z.strictObject({ ttl: z.enum(["30m", "12h"]) }).optional(),
  service_tier: identifier.optional(),
});

const chatPart = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("text"), text: z.string() }),
  z.strictObject({ type: z.literal("image_url"), image_url: z.strictObject({ url: imageData, detail }) }),
]);
const chatMessage = z.discriminatedUnion("role", [
  z.strictObject({ role: z.enum(["system", "developer"]), content: z.string() }),
  z.strictObject({ role: z.literal("user"), content: z.union([z.string(), z.array(chatPart).max(256)]) }),
  z.strictObject({
    role: z.literal("assistant"), content: z.string().nullable().optional(),
    tool_calls: z.array(z.strictObject({
      type: z.literal("function"), id: identifier,
      function: z.strictObject({ name: identifier, arguments: z.string() }),
    })).max(256).optional(),
  }),
  z.strictObject({ role: z.literal("tool"), content: z.string(), tool_call_id: identifier }),
]);
const chatRequest = z.strictObject({
  model: modelIdentifierSchema,
  messages: z.array(chatMessage).min(1).max(4096),
  stream: z.boolean().optional(),
  tools: z.array(z.strictObject({ type: z.literal("function"), function: z.strictObject(functionFields) })).max(256).optional(),
  tool_choice: z.union([
    z.enum(["auto", "none", "required"]),
    z.strictObject({ type: z.literal("function"), function: z.strictObject({ name: identifier }) }),
  ]).optional(),
  parallel_tool_calls: z.boolean().optional(),
  reasoning_effort: reasoningEffortSchema.optional(),
  response_format: z.record(z.string(), z.unknown()).optional(),
  max_tokens: outputLimit,
  temperature: z.number().min(0).max(2).optional(),
  top_p: z.number().min(0).max(1).optional(),
  seed: z.number().int().optional(),
  presence_penalty: z.number().min(-2).max(2).optional(),
  frequency_penalty: z.number().min(-2).max(2).optional(),
});

export function projectModelProxyRequest(endpoint: ModelProxyEndpoint, input: unknown, purpose: DesktopModelPurpose): {
  body: Record<string, unknown>;
  model: string;
  stream: boolean;
} {
  assertBoundedJson(input);
  const toolsAllowed = purpose === "primary";
  if (endpoint === "chat/completions") {
    const body = chatRequest.parse(input);
    if (purpose === "transition_source") {
      const last = body.messages.at(-1);
      const part = last?.role === "user" && Array.isArray(last.content) && last.content.length === 1
        ? last.content[0] : undefined;
      const prompt = last?.role === "user" && typeof last.content === "string" ? last.content
        : part?.type === "text" ? part.text : "";
      if (!nativeCompactionPrompt(prompt) || !body.stream || body.response_format !== undefined) {
        throw new AppError("FORBIDDEN");
      }
    }
    if (!toolsAllowed) {
      delete body.tools;
      delete body.tool_choice;
      delete body.parallel_tool_calls;
    }
    return { body, model: body.model, stream: body.stream === true };
  }
  const body = responseRequest.parse(input);
  if (purpose === "transition_source") {
    const last = Array.isArray(body.input) ? body.input.at(-1) : undefined;
    const part = last?.type === "message" && last.role === "user" && last.content.length === 1 ? last.content[0] : undefined;
    if (part?.type !== "input_text" || !nativeCompactionPrompt(part.text) || !body.stream || body.text?.format !== undefined) {
      throw new AppError("FORBIDDEN");
    }
  }
  delete body.client_metadata;
  delete body.prompt_cache_key;
  delete body.prompt_cache_options;
  delete body.service_tier;
  body.store = false;
  if (!toolsAllowed) {
    delete body.tools;
    delete body.tool_choice;
    delete body.parallel_tool_calls;
    if (Array.isArray(body.input)) {
      body.input = body.input.flatMap((item): z.infer<typeof responseItem>[] => {
        if (item.type === "tool_search_output") return [{ ...item, tools: [] }];
        if (item.type !== "additional_tools") return [item];
        return item.content === undefined ? [] : [{ type: "message", role: "developer", content: item.content }];
      });
    }
  }
  return { body, model: body.model, stream: body.stream === true };
}

function nativeCompactionPrompt(input: string): boolean {
  return input.length === 426 && sha256(input) === nativeCompactionPromptHash;
}

function assertBoundedJson(input: unknown): void {
  const pending = [{ value: input, depth: 0 }];
  let nodes = 0;
  while (pending.length > 0) {
    const node = pending.pop();
    if (!node) break;
    if (node.depth > 32 || ++nodes > 100_000) throw new AppError("VALIDATION_ERROR");
    if (node.value === null || typeof node.value !== "object") continue;
    for (const [key, value] of Object.entries(node.value)) {
      if (["__proto__", "prototype", "constructor"].includes(key)) throw new AppError("VALIDATION_ERROR");
      if (["$ref", "$dynamicRef", "$recursiveRef"].includes(key) &&
          (typeof value !== "string" || !value.startsWith("#"))) throw new AppError("VALIDATION_ERROR");
      pending.push({ value, depth: node.depth + 1 });
    }
  }
}
